"""Archived Elasticsearch upload experiment. Credentials have been removed."""

from elasticsearch import Elasticsearch
import json
# The original cloud identifier was removed.


# Password for the 'elastic' user generated by Elasticsearch
ELASTIC_PASSWORD = "REMOVED_ROTATE_THE_ORIGINAL_CREDENTIAL"

# Found in the 'Manage Deployment' page
CLOUD_ID = "REMOVED"

# Create the client instance
client = Elasticsearch(
    cloud_id=CLOUD_ID,
    basic_auth=("elastic", ELASTIC_PASSWORD)
)

# Successful response!
client.info()
# {'name': 'instance-0000000000', 'cluster_name': ...}


def send_json_to_elasticsearch(file_path, index_name):
    with open(file_path, 'r') as file:
        data = json.load(file)
    
    response = client.index(index=index_name, document=data)

    print("Elastic search response: ", response)


send_json_to_elasticsearch('data.json', 'FoodDB')









